 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    nonzero = Counter(v for row in grid for v in row if v)
    frame = nonzero.most_common(1)[0][0]
    # Find the centers of same-color interior patches (tiles).
    seen, marks, protected = set(), [], set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame) or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx)); stack.append((yy, xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            protected.update(cells)
            marks.append((color, (min(rs) + max(rs)) // 2, (min(cs) + max(cs)) // 2))
    out = [row[:] for row in grid]
    # The commonest patch color is ordinary; remaining colors are signals.
    ordinary = Counter(color for color, _, _ in marks).most_common(1)[0][0]
    for color, r, c in marks:
        if color == ordinary:
            continue
        # Connect only consecutive aligned occurrences, and only when the
        # intervening corridor is empty (a colored tile blocks the connection).
    for color in {color for color, _, _ in marks if color != ordinary}:
        pts = {(r, c) for col, r, c in marks if col == color}
        for r in {r for r, c in pts}:
            xs = sorted(c for rr, c in pts if rr == r)
            for a, b in zip(xs, xs[1:]):
                if all(grid[r][x] == 0 for x in range(a + 1, b)):
                    for x in range(a + 1, b): out[r][x] = color
        for c in {c for r, c in pts}:
            ys = sorted(r for r, cc in pts if cc == c)
            for a, b in zip(ys, ys[1:]):
                if all(grid[y][c] == 0 for y in range(a + 1, b)):
                    for y in range(a + 1, b): out[y][c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
