        for c in {c for r, c in points}:
            ys = sorted(r for r, cc in points if cc == c)
            for a, b in zip(ys, ys[1:]):
                for y in range(a + 1, b):
                    if grid[y][c] == 0: out[y][c] = color
    return out

if __name__ == '__main__':
